import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.uw_ZoRon.js";const h=JSON.parse('{"title":"The app model","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/the-app-model.md","filePath":"deep-dive/the-app-model.md"}'),n={name:"deep-dive/the-app-model.md"};function r(d,e,c,i,l,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="the-app-model" tabindex="-1">The app model <a class="header-anchor" href="#the-app-model" aria-label="Permalink to &quot;The app model&quot;">​</a></h1><p>A RUSM <strong>app</strong> is a project that <em>declares</em> its components and lets the runtime build, load, supervise, and run them. You describe <strong>what</strong> exists — components, their capabilities, the ports they serve — in one <code>rusm.toml</code>; the runtime owns <strong>how</strong> they start, restart, and wire together. The payoff: you write <em>source</em>, never glue.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes rose-pine-dawn rose-pine-moon catppuccin-latte catppuccin-mocha vitesse-light vitesse-dark one-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>├── rusm.toml          # node config + [components.&lt;name&gt;] (capability, resident)</span></span>
<span class="line"><span>│                       #   and/or [[serve]] listeners (protocol, listen; routes name handlers)</span></span>
<span class="line"><span>├── components/        # SOURCE — a cargo workspace, one crate per component</span></span>
<span class="line"><span>│   └── &lt;name&gt;/        # Rust (and TS via Bun + rquickjs, embedded — no jco)</span></span>
<span class="line"><span>└── wasm/              # BUILT, ready-to-run .wasm (also drop 3rd-party .wasm here)</span></span></code></pre></div><p>The manifest refers to components <strong>by name</strong>; <code>./wasm/</code> is the enforced load directory.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>One CLI drives the whole lifecycle — scaffold, build, run, watch, serve:</p><ul><li><strong><code>rusm new &lt;name&gt;</code></strong> — scaffolds a new app: a zero-dependency TypeScript HTTP component (<code>components/api/index.ts</code>, a default <code>Request</code>→<code>Response</code> handler), a <code>rusm.toml</code> with a <code>[[serve]]</code> entry, <code>.gitignore</code>, and a README. <code>rusm new hello &amp;&amp; cd hello &amp;&amp; rusm build &amp;&amp; rusm serve</code> then <code>curl http://127.0.0.1:8080/</code> works end to end.</li><li><strong><code>rusm build</code></strong> — discovers <code>components/&lt;name&gt;/</code>, builds each with one toolchain (<code>cargo build --target wasm32-wasip2</code>, which componentizes — no jco, no cargo-component), and emits <code>./wasm/&lt;name&gt;.wasm</code>.</li><li><strong><code>rusm run</code></strong> — registers each manifest component under its capability profile so a route or a sibling can <code>spawn</code> it by name; the <strong><code>resident = true</code></strong> ones are also boot-spawned and supervised (auto-restarted on crash). Code can also spawn dynamically — both work together.</li><li><strong><code>rusm dev</code></strong> — build, then run, then watch <code>./components</code> and rebuild + reload on edit.</li><li><strong><code>rusm serve</code></strong> — hosts the <code>rusm.toml</code> <strong><code>[[serve]]</code></strong> listeners (<code>protocol</code> = <code>http</code> | <code>sse</code> | <code>ws</code>, <code>listen</code>, and — for HTTP/SSE — a <code>[serve.routes]</code> table) on real TCP ports. Each listener is pure: a routed HTTP/SSE listener names its handlers in <code>[serve.routes]</code> (each a <code>[components.&lt;name&gt;]</code> entry with its own capability); a WS or routes-less HTTP listener names its single handler with <code>component</code>. Handlers load from <code>wasm/&lt;name&gt;.{wasm,js}</code> (HTTP and SSE via the <code>http_server</code> path, WS via <code>ws_server</code>). The node only serves; it never generates load.</li></ul><h2 id="environment-—-kiss-the-rust-way" tabindex="-1">Environment — KISS, the Rust way <a class="header-anchor" href="#environment-—-kiss-the-rust-way" aria-label="Permalink to &quot;Environment — KISS, the Rust way&quot;">​</a></h2><p>Env vars resolve <strong>process environment first, then a <code>.env</code></strong> fallback (via <code>dotenvy</code>; the real environment wins), exposed to guests through the standard <code>wasi:cli/environment</code> — gated by the capability profile (default-deny: grant keys or all). No wasmCloud-style <code>wasi:config/store</code>.</p><blockquote><p>Shipped in Phase 7 (<code>rusm-cli</code>).</p></blockquote>`,11)])])}const u=o(n,[["render",r]]);export{h as __pageData,u as default};
